/**
 * @file Defines the data structure for a user's request to create a new application.
 * This model captures all the initial input provided by a user to initiate the app creation process.
 */

class UserRequest {
    /**
     * Creates an instance of UserRequest.
     * @param {object} params - The parameters for the UserRequest.
     * @param {string | null} [params.id=null] - Unique identifier for the user request. Typically generated by the database.
     * @param {string} params.userId - The ID of the user making the request.
     * @param {string} params.appName - The desired name for the new application.
     * @param {string} params.appDescription - A detailed description of what the application should do.
     * @param {string[]} [params.appFeatures=[]] - An array of key features the application should have.
     * @param {string} [params.targetAudience=''] - Description of the primary target users for the application.
     * @param {string} [params.monetizationStrategy=''] - How the application is expected to generate revenue (e.g., 'freemium', 'subscription', 'ads').
     * @param {string[]} [params.technologiesPreferred=[]] - An array of preferred technologies or tech stack components (e.g., ['React', 'Node.js', 'MongoDB', 'AWS']).
     * @param {object} [params.designPreferences={}] - An object containing UI/UX design preferences (e.g., { theme: 'minimal', primaryColor: '#007bff' }).
     * @param {string} [params.status='pending'] - The current status of the request.
     *                                             Possible values: 'pending', 'queued', 'analyzing', 'planning', 'generating_code',
     *                                             'testing', 'review_needed', 'completed', 'failed', 'cancelled'.
     * @param {Date} [params.createdAt=new Date()] - The timestamp when the request was created.
     * @param {Date} [params.updatedAt=new Date()] - The timestamp when the request was last updated.
     * @param {string | null} [params.generatedAppId=null] - The ID of the Application model that was generated from this request, once completed.
     */
    constructor({
        id = null,
        userId,
        appName,
        appDescription,
        appFeatures = [],
        targetAudience = '',
        monetizationStrategy = '',
        technologiesPreferred = [],
        designPreferences = {},
        status = 'pending',
        createdAt = new Date(),
        updatedAt = new Date(),
        generatedAppId = null
    }) {
        if (!userId) {
            throw new Error('UserRequest: userId is a required field.');
        }
        if (!appName) {
            throw new Error('UserRequest: appName is a required field.');
        }
        if (!appDescription) {
            throw new Error('UserRequest: appDescription is a required field.');
        }

        this.id = id;
        this.userId = userId;
        this.appName = appName;
        this.appDescription = appDescription;
        this.appFeatures = appFeatures;
        this.targetAudience = targetAudience;
        this.monetizationStrategy = monetizationStrategy;
        this.technologiesPreferred = technologiesPreferred;
        this.designPreferences = designPreferences;
        this.status = status;
        this.createdAt = createdAt instanceof Date ? createdAt : new Date(createdAt);
        this.updatedAt = updatedAt instanceof Date ? updatedAt : new Date(updatedAt);
        this.generatedAppId = generatedAppId;
    }

    /**
     * Updates the status of the user request.
     * @param {string} newStatus - The new status to set.
     */
    updateStatus(newStatus) {
        // Optional: Add validation logic for newStatus here (e.g., check against allowed enum values)
        this.status = newStatus;
        this.updatedAt = new Date();
    }

    /**
     * Converts the UserRequest instance into a plain JavaScript object, suitable for
     * serialization (e.g., saving to a database or sending over an API).
     * @returns {object} A plain object representation of the UserRequest.
     */
    toObject() {
        return {
            id: this.id,
            userId: this.userId,
            appName: this.appName,
            appDescription: this.appDescription,
            appFeatures: this.appFeatures,
            targetAudience: this.targetAudience,
            monetizationStrategy: this.monetizationStrategy,
            technologiesPreferred: this.technologiesPreferred,
            designPreferences: this.designPreferences,
            status: this.status,
            createdAt: this.createdAt.toISOString(), // ISO string for consistent date handling
            updatedAt: this.updatedAt.toISOString(),
            generatedAppId: this.generatedAppId
        };
    }

    /**
     * Creates a UserRequest instance from a plain JavaScript object (e.g., loaded from a database).
     * @param {object} obj - The plain object containing UserRequest data.
     * @returns {UserRequest | null} A new UserRequest instance, or null if the input object is invalid.
     */
    static fromObject(obj) {
        if (!obj || typeof obj !== 'object') {
            return null;
        }
        // Destructure and ensure required fields are present before instantiating
        const { id, userId, appName, appDescription, ...rest } = obj;
        if (!userId || !appName || !appDescription) {
            console.error('UserRequest.fromObject: Missing required fields (userId, appName, appDescription).');
            return null;
        }

        return new UserRequest({ id, userId, appName, appDescription, ...rest });
    }
}

module.exports = UserRequest;
